  for (const item of items) {
    const block = item[1];
    const get = (tag) => {
      let m = block.match(new RegExp(`<${tag}>([\s\S]*?)<\/${tag}>`));
      if (!m) m = block.match(new RegExp(`<${tag}><!\[CDATA\[([\s\S]*?)\]\]><\/${tag}>`));
      return m ? m[1].replace(/\s+/g,' ').trim() : '';
    };
    console.log('- title:', get('title'));
    console.log('  pubDate:', get('pubDate'));
    console.log('  link:', get('link') || get('guid'));
  }
}
