const {execSync} = require('child_process');
const feeds = [
  ['CoinDesk','https://www.coindesk.com/arc/outboundfeeds/rss'],
  ['CoinTelegraph','https://cointelegraph.com/rss'],
  ['Decrypt','https://decrypt.co/feed'],
  ['GoogleNews','https://news.google.com/rss/search?q=bitcoin+crypto&hl=en-US&gl=US&ceid=US:en']
];
function extract(tag, block){
  const open = `<${tag}>`;
  const close = `</${tag}>`;
  let s = block.indexOf(open);
  if (s < 0) return '';
  s += open.length;
  let e = block.indexOf(close, s);
  if (e < 0) return '';
  let v = block.slice(s,e).replace(/^<!\[CDATA\[/,'').replace(/\]\]>$/,'');
  return v.replace(/\s+/g,' ').trim();
}
for (const [name,url] of feeds) {
  console.log('###', name);
  const xml = execSync(`curl -L -s --max-time 20 ${JSON.stringify(url)}`, {encoding:'utf8', maxBuffer: 12*1024*1024});
  const items = xml.split(/<item>/).slice(1,8);
  for (const item of items) {
    console.log('- title:', extract('title', item));
    console.log('  pubDate:', extract('pubDate', item));
    console.log('  link:', extract('link', item) || extract('guid', item));
  }
}
